#!/usr/bin/env node
/**
 * Actual Budget CLI for OpenClaw Finance Agent
 * Wraps @actual-app/api for command-line access
 */

const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '..', '.env') });

const DATA_DIR = path.join(__dirname, '..', '.actual-cache');

// Lazy-load the API to allow for graceful error handling
let api;
async function getApi() {
  if (!api) {
    try {
      api = require('@actual-app/api');
    } catch (e) {
      console.error('Error: @actual-app/api not installed. Run: npm install @actual-app/api');
      process.exit(1);
    }
  }
  return api;
}

// Configuration from environment
const config = {
  serverURL: process.env.ACTUAL_SERVER_URL,
  password: process.env.ACTUAL_PASSWORD,
  syncId: process.env.ACTUAL_SYNC_ID,
  encryptionPassword: process.env.ACTUAL_ENCRYPTION_PASSWORD,
};

function validateConfig() {
  const missing = [];
  if (!config.serverURL) missing.push('ACTUAL_SERVER_URL');
  if (!config.password) missing.push('ACTUAL_PASSWORD');
  if (!config.syncId) missing.push('ACTUAL_SYNC_ID');

  if (missing.length > 0) {
    console.error('Missing required environment variables:', missing.join(', '));
    console.error('Please configure .env file in the agent workspace.');
    process.exit(1);
  }
}

async function initApi() {
  const api = await getApi();
  const fs = require('fs');

  // Ensure data directory exists
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }

  await api.init({
    dataDir: DATA_DIR,
    serverURL: config.serverURL,
    password: config.password,
  });

  const downloadOpts = config.encryptionPassword 
    ? { password: config.encryptionPassword }
    : undefined;

  await api.downloadBudget(config.syncId, downloadOpts);
}

async function shutdown() {
  const api = await getApi();
  await api.shutdown();
}

// ============ COMMANDS ============

async function listAccounts() {
  const api = await getApi();
  const accounts = await api.getAccounts();

  console.log('\n📊 ACCOUNTS\n');
  console.log('| Account | Type | Balance | Status |');
  console.log('|---------|------|---------|--------|');

  for (const acct of accounts) {
    if (acct.closed) continue;
    const balance = await api.getAccountBalance(acct.id);
    const balanceStr = formatMoney(balance);
    const type = acct.offbudget ? 'Off-budget' : 'On-budget';
    console.log(`| ${acct.name} | ${type} | ${balanceStr} | Active |`);
  }

  // Show closed accounts separately
  const closed = accounts.filter(a => a.closed);
  if (closed.length > 0) {
    console.log('\nClosed accounts:', closed.map(a => a.name).join(', '));
  }
}

async function listTransactions(options) {
  const api = await getApi();
  const accounts = await api.getAccounts();

  const days = options.days || 30;
  const endDate = new Date();
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  const startStr = formatDate(startDate);
  const endStr = formatDate(endDate);

  let allTransactions = [];

  for (const acct of accounts) {
    if (acct.closed) continue;
    if (options.account && !acct.name.toLowerCase().includes(options.account.toLowerCase())) {
      continue;
    }

    const txns = await api.getTransactions(acct.id, startStr, endStr);
    allTransactions.push(...txns.map(t => ({ ...t, accountName: acct.name })));
  }

  // Get categories and payees for display
  const categories = await api.getCategories();
  const categoryMap = new Map(categories.map(c => [c.id, c.name]));

  const payees = await api.getPayees();
  const payeeMap = new Map(payees.map(p => [p.id, p.name]));

  // Apply filters
  if (options.uncategorized) {
    allTransactions = allTransactions.filter(t => !t.category);
  }
  if (options.category) {
    const catId = categories.find(c => 
      c.name.toLowerCase().includes(options.category.toLowerCase())
    )?.id;
    if (catId) {
      allTransactions = allTransactions.filter(t => t.category === catId);
    }
  }
  if (options.min) {
    const minAmount = Math.abs(parseFloat(options.min) * 100);
    allTransactions = allTransactions.filter(t => Math.abs(t.amount) >= minAmount);
  }
  if (options.max) {
    const maxAmount = Math.abs(parseFloat(options.max) * 100);
    allTransactions = allTransactions.filter(t => Math.abs(t.amount) <= maxAmount);
  }

  // Sort by date descending
  allTransactions.sort((a, b) => new Date(b.date) - new Date(a.date));

  console.log(`\n📋 TRANSACTIONS (last ${days} days)\n`);

  if (allTransactions.length === 0) {
    console.log('No transactions found matching criteria.');
    return;
  }

  console.log('| Date | Account | Payee | Category | Amount |');
  console.log('|------|---------|-------|----------|--------|');

  for (const t of allTransactions.slice(0, 50)) { // Limit output
    const payeeName = payeeMap.get(t.payee_id) || t.imported_payee || 'Unknown';
    const categoryName = categoryMap.get(t.category) || '❓ Uncategorized';
    const amount = formatMoney(t.amount);
    console.log(`| ${t.date} | ${t.accountName} | ${payeeName} | ${categoryName} | ${amount} |`);
  }

  if (allTransactions.length > 50) {
    console.log(`\n... and ${allTransactions.length - 50} more transactions`);
  }

  // Summary
  const total = allTransactions.reduce((sum, t) => sum + t.amount, 0);
  console.log(`\n**Total**: ${formatMoney(total)} across ${allTransactions.length} transactions`);
}

async function showBudget(options) {
  const api = await getApi();

  const month = options.month || formatMonth(new Date());
  const budget = await api.getBudgetMonth(month);

  console.log(`\n💰 BUDGET FOR ${month}\n`);

  if (options.category) {
    // Show specific category
    const categories = await api.getCategories();
    const cat = categories.find(c => 
      c.name.toLowerCase().includes(options.category.toLowerCase())
    );

    if (!cat) {
      console.log(`Category "${options.category}" not found.`);
      return;
    }

    const catBudget = budget.categoryGroups
      .flatMap(g => g.categories)
      .find(c => c.id === cat.id);

    if (catBudget) {
      console.log(`**${cat.name}**`);
      console.log(`- Budgeted: ${formatMoney(catBudget.budgeted)}`);
      console.log(`- Spent: ${formatMoney(catBudget.spent)}`);
      console.log(`- Balance: ${formatMoney(catBudget.balance)}`);

      const pctUsed = catBudget.budgeted ? 
        Math.round((Math.abs(catBudget.spent) / catBudget.budgeted) * 100) : 0;
      console.log(`- Used: ${pctUsed}%`);
    }
    return;
  }

  // Show all categories
  console.log('| Category | Budgeted | Spent | Balance | Status |');
  console.log('|----------|----------|-------|---------|--------|');

  let totalBudgeted = 0;
  let totalSpent = 0;

  for (const group of budget.categoryGroups) {
    if (group.is_income) continue; // Skip income categories for expense view

    for (const cat of group.categories || []) {
      const budgeted = cat.budgeted || 0;
      const spent = cat.spent || 0;
      const balance = cat.balance || 0;

      totalBudgeted += budgeted;
      totalSpent += spent;

      let status = '✅';
      if (balance < 0) status = '🔴 Over';
      else if (budgeted > 0 && Math.abs(spent) > budgeted * 0.9) status = '⚠️ High';

      console.log(`| ${cat.name} | ${formatMoney(budgeted)} | ${formatMoney(spent)} | ${formatMoney(balance)} | ${status} |`);
    }
  }

  console.log('|----------|----------|-------|---------|--------|');
  console.log(`| **TOTAL** | ${formatMoney(totalBudgeted)} | ${formatMoney(totalSpent)} | ${formatMoney(totalBudgeted + totalSpent)} | |`);
}

async function listCategories() {
  const api = await getApi();
  const groups = await api.getCategoryGroups();

  console.log('\n📁 CATEGORIES\n');

  for (const group of groups) {
    const type = group.is_income ? '(Income)' : '';
    console.log(`\n**${group.name}** ${type}`);

    for (const cat of group.categories || []) {
      console.log(`  - ${cat.name}`);
    }
  }
}

async function showInsights(options) {
  const api = await getApi();
  const months = options.months || 3;
  const type = options.type || 'spending';

  console.log(`\n📈 INSIGHTS (${type}, last ${months} months)\n`);

  const accounts = await api.getAccounts();
  const categories = await api.getCategories();
  const categoryMap = new Map(categories.map(c => [c.id, c.name]));

  // Calculate date range
  const endDate = new Date();
  const startDate = new Date();
  startDate.setMonth(startDate.getMonth() - months);

  // Gather all transactions
  let allTransactions = [];
  for (const acct of accounts) {
    if (acct.closed || acct.offbudget) continue;
    const txns = await api.getTransactions(acct.id, formatDate(startDate), formatDate(endDate));
    allTransactions.push(...txns);
  }

  // Filter to expenses only (negative amounts)
  const expenses = allTransactions.filter(t => t.amount < 0 && t.category);

  if (type === 'spending' || type === 'category') {
    // Category breakdown
    const byCategory = new Map();
    for (const t of expenses) {
      const catName = categoryMap.get(t.category) || 'Uncategorized';
      byCategory.set(catName, (byCategory.get(catName) || 0) + Math.abs(t.amount));
    }

    const sorted = [...byCategory.entries()].sort((a, b) => b[1] - a[1]);

    console.log('| Category | Total | Monthly Avg |');
    console.log('|----------|-------|-------------|');

    for (const [cat, total] of sorted.slice(0, 15)) {
      const monthly = Math.round(total / months);
      console.log(`| ${cat} | ${formatMoney(total)} | ${formatMoney(monthly)} |`);
    }

    const grandTotal = sorted.reduce((sum, [, amt]) => sum + amt, 0);
    console.log(`\n**Total Spending**: ${formatMoney(grandTotal)} (${formatMoney(Math.round(grandTotal / months))}/month)`);
  }

  if (type === 'subscriptions') {
    // Look for recurring transactions
    console.log('Analyzing recurring transactions...\n');

    const payees = await api.getPayees();
    const payeeMap = new Map(payees.map(p => [p.id, p.name]));

    // Group by payee and look for monthly patterns
    const byPayee = new Map();
    for (const t of expenses) {
      const payeeName = payeeMap.get(t.payee_id) || 'Unknown';
      if (!byPayee.has(payeeName)) byPayee.set(payeeName, []);
      byPayee.get(payeeName).push(t);
    }

    console.log('Potential subscriptions (appearing monthly):\n');
    console.log('| Service | Amount | Frequency |');
    console.log('|---------|--------|-----------|');

    for (const [payee, txns] of byPayee) {
      if (txns.length >= months - 1) {
        // Likely recurring
        const avgAmount = Math.abs(txns.reduce((s, t) => s + t.amount, 0) / txns.length);
        console.log(`| ${payee} | ${formatMoney(avgAmount)} | ~Monthly |`);
      }
    }
  }
}

async function syncBudget() {
  const api = await getApi();
  console.log('Syncing with Actual Budget server...');
  await api.sync();
  console.log('✅ Sync complete!');
}

// ============ HELPERS ============

function formatMoney(cents) {
  const dollars = (cents / 100).toFixed(2);
  return cents >= 0 ? `$${dollars}` : `-$${Math.abs(dollars).toFixed(2)}`;
}

function formatDate(date) {
  return date.toISOString().split('T')[0];
}

function formatMonth(date) {
  return date.toISOString().slice(0, 7);
}

function parseArgs(args) {
  const options = {};
  let command = null;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (!arg.startsWith('-') && !command) {
      command = arg;
    } else if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const next = args[i + 1];

      if (next && !next.startsWith('-')) {
        options[key] = next;
        i++;
      } else {
        options[key] = true;
      }
    }
  }

  return { command, options };
}

// ============ MAIN ============

async function main() {
  const { command, options } = parseArgs(process.argv.slice(2));

  if (!command || command === 'help') {
    console.log(`
Actual Budget CLI for OpenClaw

Usage: node actual-cli.js <command> [options]

Commands:
  accounts              List all accounts with balances
  transactions          Get transactions
  budget                Show budget status
  categories            List all categories
  insights              Spending analysis
  sync                  Force sync with server
  help                  Show this help

Transaction Options:
  --days N              Last N days (default: 30)
  --account NAME        Filter by account name
  --category NAME       Filter by category
  --uncategorized       Only uncategorized transactions
  --min AMOUNT          Minimum amount in dollars
  --max AMOUNT          Maximum amount in dollars

Budget Options:
  --month YYYY-MM       Specific month (default: current)
  --category NAME       Show specific category detail

Insights Options:
  --type TYPE           spending | subscriptions (default: spending)
  --months N            Months to analyze (default: 3)
`);
    return;
  }

  validateConfig();

  try {
    await initApi();

    switch (command) {
      case 'accounts':
        await listAccounts();
        break;
      case 'transactions':
        await listTransactions(options);
        break;
      case 'budget':
        await showBudget(options);
        break;
      case 'categories':
        await listCategories();
        break;
      case 'insights':
        await showInsights(options);
        break;
      case 'sync':
        await syncBudget();
        break;
      default:
        console.error(`Unknown command: ${command}`);
        console.log('Run with "help" for usage information.');
    }
  } catch (error) {
    console.error('Error:', error.message);
    if (process.env.DEBUG) console.error(error.stack);
  } finally {
    await shutdown();
  }
}

main();

